import json
from jinja2 import Template

with open('/app/output/report_data.json', 'r') as f:
    data = json.load(f)
with open('/app/output/charts.json', 'r') as f:
    charts = json.load(f)

kpis = data['kpis']
bw = data['best_worst']

html_template = """
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Amazon Product Catalog Performance & Customer Sentiment Analysis</title>
<style>
  :root {
    --bg: #f4f6f8;
    --card: #ffffff;
    --text: #1a1a2e;
    --muted: #5a5a6e;
    --accent: #2563eb;
    --accent2: #059669;
    --accent3: #d97706;
    --accent4: #dc2626;
    --border: #e2e8f0;
  }
  * { box-sizing: border-box; }
  body {
    font-family: "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: var(--bg);
    color: var(--text);
    margin: 0;
    padding: 0;
    line-height: 1.6;
  }
  .container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 24px;
  }
  header {
    border-bottom: 3px solid var(--accent);
    padding-bottom: 16px;
    margin-bottom: 24px;
  }
  header h1 { margin: 0; font-size: 1.7rem; }
  header p { margin: 6px 0 0; color: var(--muted); font-size: 0.95rem; }
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
  }
  .kpi-card {
    background: var(--card);
    border-radius: 10px;
    padding: 18px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.06);
    text-align: center;
    border-top: 4px solid var(--accent);
  }
  .kpi-card .value { font-size: 1.6rem; font-weight: 700; color: var(--text); }
  .kpi-card .label { font-size: 0.78rem; color: var(--muted); margin-top: 4px; text-transform: uppercase; letter-spacing: 0.4px; }
  .kpi-card.accent-green { border-top-color: var(--accent2); }
  .kpi-card.accent-amber { border-top-color: var(--accent3); }
  .kpi-card.accent-red { border-top-color: var(--accent4); }
  section {
    background: var(--card);
    border-radius: 10px;
    padding: 22px 24px;
    margin-bottom: 22px;
    box-shadow: 0 2px 6px rgba(0,0,0,0.06);
  }
  section h2 {
    font-size: 1.25rem;
    margin: 0 0 12px;
    padding-bottom: 8px;
    border-bottom: 2px solid var(--border);
  }
  section h3 { font-size: 1.05rem; margin: 18px 0 8px; color: var(--muted); }
  p { margin: 8px 0; }
  .insight { background: #eef2ff; border-left: 4px solid var(--accent); padding: 10px 14px; border-radius: 6px; margin: 10px 0; font-size: 0.95rem; }
  .chart { text-align: center; margin: 14px 0; }
  .chart img { max-width: 100%; height: auto; border-radius: 8px; border: 1px solid var(--border); }
  table { width: 100%; border-collapse: collapse; margin: 10px 0; font-size: 0.92rem; }
  th, td { padding: 10px 8px; border-bottom: 1px solid var(--border); text-align: left; }
  th { background: #f8fafc; font-weight: 600; }
  tr:hover { background: #f8fafc; }
  .badge { display:inline-block; padding: 2px 8px; border-radius: 12px; font-size: 0.75rem; font-weight: 600; }
  .badge-green { background:#d1fae5; color:#065f46; }
  .badge-amber { background:#fef3c7; color:#92400e; }
  .badge-red { background:#fee2e2; color:#991b1b; }
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
  @media (max-width: 860px) { .two-col { grid-template-columns: 1fr; } }
  footer { text-align: center; color: var(--muted); font-size: 0.85rem; padding: 18px; }
  ul.recs { padding-left: 18px; }
  ul.recs li { margin-bottom: 14px; }
  .rec-title { font-weight: 700; color: var(--text); }
  .rec-meta { color: var(--muted); font-size: 0.92rem; }
</style>
</head>
<body>
<div class="container">
  <header>
    <h1>Amazon Product Catalog Performance & Customer Sentiment Analysis</h1>
    <p>1,465 products analyzed across pricing, discounting, ratings, and category performance &mdash; enabling data-driven assortment and promotional decisions.</p>
  </header>

  <!-- Executive Overview -->
  <section id="executive-overview">
    <h2>Executive Overview</h2>
    <div class="kpi-grid">
      <div class="kpi-card accent-green">
        <div class="value">{{ kpis.avg_rating }}</div>
        <div class="label">Average Rating</div>
      </div>
      <div class="kpi-card accent-amber">
        <div class="value">{{ kpis.avg_discount_pct }}%</div>
        <div class="label">Average Discount</div>
      </div>
      <div class="kpi-card">
        <div class="value">{{ kpis.median_rating_count }}</div>
        <div class="label">Median Rating Count</div>
      </div>
      <div class="kpi-card accent-green">
        <div class="value">{{ kpis.high_rating_share }}%</div>
        <div class="label">High-Rating Share (≥4.0)</div>
      </div>
      <div class="kpi-card accent-red">
        <div class="value">{{ kpis.price_discount_efficiency }}</div>
        <div class="label">Discount↔Rating Correlation</div>
      </div>
      <div class="kpi-card">
        <div class="value">₹{{ "{:,.0f}".format(kpis.avg_discounted_price) }}</div>
        <div class="label">Avg Discounted Price</div>
      </div>
    </div>

    <div class="insight">
      <strong>Headline:</strong> Three in four products ({{ kpis.high_rating_share }}%) earn a 4.0+ star rating, yet deeper discounts are <em>negatively</em> correlated with satisfaction (r = {{ kpis.price_discount_efficiency }}). Discounts drive volume, not delight — the median product attracts {{ "{:,}".format(kpis.median_rating_count) }} ratings, but discount depth has almost no relationship with review volume (r = {{ kpis.discount_rating_count_corr }}). Management should treat promotions as a traffic tool, not a quality proxy.
    </div>
  </section>

  <!-- Category Performance -->
  <section id="category-analysis">
    <h2>Category Performance Breakdown</h2>
    <p>The catalog spans {{ data.category_stats|length }} top-level categories, led by <strong>Electronics</strong> ({{ data.category_stats[4].product_count }} products) and <strong>Home & Kitchen</strong> ({{ data.category_stats[5].product_count }} products). The chart below ranks categories by average customer rating and flags relative performance against the catalog mean.</p>
    <div class="chart"><img src="data:image/png;base64,{{ charts.category_rating_bar }}" alt="Category Rating Bar Chart"></div>

    <h3>Best & Worst Performers</h3>
    <div class="two-col">
      <div>
        <p><span class="badge badge-green">Best Rating</span> <strong>{{ bw.best_rating_category }}</strong> &mdash; {{ bw.best_rating_value }} ★</p>
        <p><span class="badge badge-red">Lowest Rating</span> <strong>{{ bw.worst_rating_category }}</strong> &mdash; {{ bw.worst_rating_value }} ★</p>
      </div>
      <div>
        <p><span class="badge badge-green">Most Engaged</span> <strong>{{ bw.best_engagement_category }}</strong> &mdash; {{ "{:,.0f}".format(bw.best_engagement_value) }} avg ratings</p>
        <p><span class="badge badge-red">Least Engaged</span> <strong>{{ bw.worst_engagement_category }}</strong> &mdash; {{ "{:,.0f}".format(bw.worst_engagement_value) }} avg ratings</p>
      </div>
    </div>

    <h3>Top Sub-Categories by Volume</h3>
    <table>
      <tr><th>Sub-Category</th><th>Parent</th><th>Products</th><th>Avg Rating</th><th>Avg Discount</th></tr>
      {% for s in data.sub_category_stats %}
      <tr>
        <td>{{ s.sub_category }}</td>
        <td>{{ s.top_category }}</td>
        <td>{{ s.product_count }}</td>
        <td>{{ "%.2f"|format(s.avg_rating) }}</td>
        <td>{{ "%.1f"|format(s.avg_discount) }}%</td>
      </tr>
      {% endfor %}
    </table>
  </section>

  <!-- Pricing & Discount Strategy -->
  <section id="pricing-discount-analysis">
    <h2>Pricing & Discount Strategy Analysis</h2>
    <p>This section quantifies the relationship between price, discount depth, and customer satisfaction — the highest-value insight for management.</p>

    <div class="insight">
      <strong>Key Finding:</strong> Discount depth and rating show a <strong>weak negative correlation (r = {{ kpis.price_discount_efficiency }})</strong>. Deeper discounts do not buy higher satisfaction; if anything, they modestly coincide with lower ratings. Discount depth is also essentially uncorrelated with review volume (r = {{ kpis.discount_rating_count_corr }}).
    </div>

    <div class="chart"><img src="data:image/png;base64,{{ charts.discount_rating_bar }}" alt="Discount vs Rating"></div>

    <h3>Price Segment Lens</h3>
    <p>Breaking the catalog into price tiers reveals where discounts are concentrated and whether they deliver returns.</p>
    <div class="chart"><img src="data:image/png;base64,{{ charts.price_segment_combo }}" alt="Price Segment Combo Chart"></div>

    <table>
      <tr><th>Price Segment</th><th>Products</th><th>Avg Rating</th><th>Avg Discount</th><th>Avg Actual Price</th></tr>
      {% for p in data.price_segment_stats %}
      <tr>
        <td>{{ p.price_segment }}</td>
        <td>{{ p.product_count }}</td>
        <td>{{ "%.2f"|format(p.avg_rating) }}</td>
        <td>{{ "%.1f"|format(p.avg_discount) }}%</td>
        <td>₹{{ "{:,.0f}".format(p.avg_actual_price) }}</td>
      </tr>
      {% endfor %}
    </table>

    <h3>Correlation Matrix</h3>
    <div class="chart"><img src="data:image/png;base64,{{ charts.correlation_heatmap }}" alt="Correlation Heatmap"></div>
  </section>

  <!-- Customer Engagement -->
  <section id="customer-engagement">
    <h2>Customer Engagement & Rating Distribution</h2>
    <p>Engagement is heavily right-skewed: a small set of products accumulates the vast majority of ratings. Understanding this distribution helps identify hero products and long-tail risks.</p>
    <div class="chart"><img src="data:image/png;base64,{{ charts.rating_distribution }}" alt="Rating Distribution"></div>

    <h3>Most Reviewed Products</h3>
    <div class="chart"><img src="data:image/png;base64,{{ charts.top_engaged }}" alt="Top Engaged Products"></div>

    <div class="insight">
      <strong>Engagement Insight:</strong> The top-reviewed products cluster in Electronics and Computers & Accessories, typically priced under ₹1,000 and carrying moderate-to-high discounts. High engagement does not guarantee high ratings — several top-SKUs sit at or below the 4.0 threshold, amplifying negative sentiment reach.
    </div>
  </section>

  <!-- Review Sentiment Snapshot -->
  <section id="review-sentiment-snapshot">
    <h2>Review Sentiment Snapshot</h2>
    <p>A keyword analysis of review titles surfaces the dominant themes customers use to describe their experience.</p>
    <div class="chart"><img src="data:image/png;base64,{{ charts.sentiment_keywords }}" alt="Sentiment Keywords"></div>

    <div class="two-col">
      <div>
        <h3>Positive Themes ({{ data.sentiment.total_positive_mentions }} mentions)</h3>
        <ul>
          {% for word, count in data.sentiment.top_positive %}
          <li><strong>{{ word }}</strong> &mdash; {{ count }} mentions</li>
          {% endfor %}
        </ul>
      </div>
      <div>
        <h3>Negative Themes ({{ data.sentiment.total_negative_mentions }} mentions)</h3>
        <ul>
          {% for word, count in data.sentiment.top_negative %}
          <li><strong>{{ word }}</strong> &mdash; {{ count }} mentions</li>
          {% endfor %}
        </ul>
      </div>
    </div>

    <div class="insight">
      <strong>Sentiment Takeaway:</strong> Positive language dominates, but negative keywords (&ldquo;poor,&rdquo; &ldquo;defective,&rdquo; &ldquo;waste&rdquo;) are concentrated enough to signal recurring quality risks — especially in high-volume categories where a single bad SKU can accumulate thousands of visible complaints.
    </div>
  </section>

  <!-- Strategic Recommendations -->
  <section id="recommendations">
    <h2>Strategic Recommendations</h2>
    <ul class="recs">
      {% for rec in data.recommendations %}
      <li>
        <div class="rec-title">{{ rec.title }}</div>
        <div class="rec-meta"><strong>Data point:</strong> {{ rec.insight }}</div>
        <div class="rec-meta"><strong>Action:</strong> {{ rec.action }}</div>
      </li>
      {% endfor %}
    </ul>
  </section>

  <footer>
    Generated on 2026-04-29 &middot; Dataset: 1,465 Amazon India products &middot; Analysis based solely on provided data.csv
  </footer>
</div>
</body>
</html>
"""

template = Template(html_template)
rendered = template.render(data=data, charts=charts, kpis=kpis, bw=bw)

with open('/app/output/final_report.html', 'w', encoding='utf-8') as f:
    f.write(rendered)

print("Report written to /app/output/final_report.html")
